	/** The From display name of mail sent as this mailbox. */
	displayName?: string
	/** IMAP, for a connected mailbox. */
	imap?: MailServer
	/** SMTP submission, for a connected mailbox. */
	smtp?: MailServer
	/** The login password of both servers; write-only, sealed at rest. */
