/** The progress of a Broadcast. */
export type BroadcastState = 'draft' | 'scheduled' | 'sending' | 'sent' | 'cancelled' | (string & {})

/** A Notify channel. */
export type Channel = 'email' | 'sms' | 'push' | 'inbox' | (string & {})

/** The state of one channel delivery. */
export type ChannelDeliveryState = 'pending' | 'sent' | 'delivered' | 'bounced' | 'failed' | 'skipped' | 'captured' | 'suppressed' | (string & {})

/** How an Email Domain's mail reaches the platform. */
export type EmailDomainReceivingMode = 'all' | (string & {})

/** Whether the platform receives mail for an Email Domain. */
export type EmailDomainReceivingState = 'disabled' | 'pending' | 'verified' | 'degraded' | (string & {})

/** Whether an Inbound Email came in or went out. */
export type InboundEmailDirection = 'received' | 'sent' | (string & {})

/** The state of an inbox item. */
export type InboxItemState = 'unread' | 'read' | 'archived' | (string & {})

/** How a mail server connection is secured. */
export type MailServerSecurity = 'tls' | 'starttls' | (string & {})

/** How a Mailbox receives mail. */
export type MailboxKind = 'connected' | 'hosted' | (string & {})

/** The state of a Message. */
export type MessageState = 'accepted' | 'suppressed' | 'delivering' | 'delivered' | 'failed' | 'cancelled' | 'rate_limited' | (string & {})

/** A push platform. */
export type PushPlatform = 'apns' | 'fcm' | 'web_push' | (string & {})

/** What happens to mail judged spam on a Route. */
export type RouteSpamPolicy = 'deliver' | 'drop' | 'reject' | (string & {})

/** Why an address is suppressed. */
export type SuppressionReason = 'bounce' | 'complaint' | 'carrier_opt_out' | 'unsubscribe' | 'uninstalled' | 'manual' | (string & {})

