/**
 * NotifyService is Sylphx Notify: messages to people over email, SMS, push,
 * and in-app inbox, with preferences, suppression, templates, and broadcasts.
 * Notify is built on Sylphx Events as an ordinary customer.
 *
 * Namespace of Sylphx Notify on `Sylphx`.
 */
export class NotifyApi {
	/** The `mail_domains` collection. */
	readonly mailDomains: MailDomainsCollection
	/** The `mail_routes` collection. */
	readonly mailRoutes: MailRoutesCollection
	/** The `senders` collection. */
	readonly senders: SendersCollection
	/** The `recipients` collection. */
	readonly recipients: RecipientsCollection
	/** The `preferences` collection. */
	readonly preferences: PreferencesCollection
	/** The `suppressions` collection. */
	readonly suppressions: SuppressionsCollection
	/** The `templates` collection. */
	readonly templates: TemplatesCollection
	/** The `messages` collection. */
	readonly messages: MessagesCollection
	/** The `mailboxes` collection. */
	readonly mailboxes: MailboxesCollection
	/** The `inbound_emails` collection. */
	readonly inboundEmails: InboundEmailsCollection
	/** The `inbox_items` collection. */
	readonly inboxItems: InboxItemsCollection
	/** The `broadcasts` collection. */
	readonly broadcasts: BroadcastsCollection

	constructor(client: runtime.Client) {
		this.mailDomains = new MailDomainsCollection(client)
		this.mailRoutes = new MailRoutesCollection(client)
		this.senders = new SendersCollection(client)
		this.recipients = new RecipientsCollection(client)
		this.preferences = new PreferencesCollection(client)
		this.suppressions = new SuppressionsCollection(client)
		this.templates = new TemplatesCollection(client)
		this.messages = new MessagesCollection(client)
		this.mailboxes = new MailboxesCollection(client)
		this.inboundEmails = new InboundEmailsCollection(client)
		this.inboxItems = new InboxItemsCollection(client)
		this.broadcasts = new BroadcastsCollection(client)
	}
}

